commands.command:
/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
const entries=[];
function walk(dir) { for (const e of fs.readdirSync(dir,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name))) { const p=path.join(dir,e.name); if(p==='recovery.json') continue; if(e.isDirectory()) walk(p); else if(e.isFile()) entries.push([p,createHash('sha256').update(fs.readFileSync(p)).digest('hex')]); else if(e.isSymbolicLink()) entries.push([p,fs.readlinkSync(p)]); } }
walk('.');
console.log(JSON.stringify({files:entries.length,digest:createHash('sha256').update(JSON.stringify(entries)).digest('hex'),result_exists:fs.existsSync('result-not-yet-received.json')}));
NODE"

/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
const report=JSON.parse(fs.readFileSync('recovery.json','utf8'));
assert.deepEqual(Object.keys(report).sort(),['action','missing_evidence','next_action','redispatched']);
assert.equal(report.redispatched,false);
assert.ok(report.action && report.next_action && report.missing_evidence.length);
const entries=[];
function walk(dir) { for (const e of fs.readdirSync(dir,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name))) { const p=path.join(dir,e.name); if(p==='recovery.json') continue; if(e.isDirectory()) walk(p); else if(e.isFile()) entries.push([p,createHash('sha256').update(fs.readFileSync(p)).digest('hex')]); else if(e.isSymbolicLink()) entries.push([p,fs.readlinkSync(p)]); } }
walk('.');
console.log(JSON.stringify({files:entries.length,digest:createHash('sha256').update(JSON.stringify(entries)).digest('hex'),result_exists:fs.existsSync('result-not-yet-received.json')}));
NODE"

